//! The SpacetimeDB Rust client SDK, which enables native Rust applications
//! to communicate with SpacetimeDB modules.
//!
//! This library depends on a set of module-specific definitions
//! autogenerated by [the SpacetimeDB CLI](https://spacetimedb.com/install).
//! See [the SpacetimeDB Rust client SDK reference](https://spacetimedb.com/docs/clients/rust#generate-module-bindings)
//! for more oh how to generate these bindings.
//!
//! A client can also compile a Rust module's source in place of generated bindings.
//! Write `extern crate spacetimedb_sdk as spacetimedb;` at the client's crate root,
//! so that the module source's `spacetimedb::...` paths resolve to this crate.
//! Then list the module's items in `spacetimedb::client_module!`, in a module of its own,
//! because it defines items with fixed names, such as `DbConnection` and `Reducer`.
//!
//! Generated bindings expand into the client API through this crate's procedural macros,
//! which run each time the crate that contains the bindings compiles.
//! For a large module, put the bindings in a crate of their own,
//! so that editing client code doesn't expand them again.

// Any `#[doc(hidden)]` modules or uses are public because
// code generated by the CLI's codegen references them,
// but users should not.

mod callbacks;
mod client_cache;
mod compression;
mod db_connection;
mod metrics;
mod spacetime_module;
mod subscription;
mod websocket;

pub mod credentials;
