pub use spacetimedb_lib::{ConnectionId, Identity, ScheduleAt, TimeDuration, Timestamp, Uuid};
pub use spacetimedb_sats::{i256, u256};

// The client expansions of the module macros (proposal 0040).
// Generated bindings name them as `spacetimedb::table` and so on, with `use spacetimedb_sdk as spacetimedb;` in scope.
// Module source can use them with `extern crate spacetimedb_sdk as spacetimedb;` at the crate root,
// which is why they are at the root rather than in a module of their own.
// A client that glob-imports both this crate and another crate with a macro of the same name,
// such as `view!` from `leptos::prelude::*`, `table!` from `prettytable`,
// or the `SpacetimeType` derive from `spacetimedb_lib` (or `spacetimedb_sats`),
// must now import that macro explicitly, because the two globs make the name ambiguous.
#[doc(hidden)]
pub use spacetimedb_bindings_macro::{
    client_module, client_procedure as procedure, client_reducer as reducer, client_table as table,
    client_view as view, ClientSpacetimeType as SpacetimeType,
};

// Placeholders, so that module source that imports the module library's context types resolves on the client.
// The client expansions discard the signatures and bodies of reducers, procedures and views,
// so these types are never used.
#[doc(hidden)]
pub enum ReducerContext {}
#[doc(hidden)]
pub enum ProcedureContext {}
#[doc(hidden)]
pub enum ViewContext {}
#[doc(hidden)]
pub enum AnonymousViewContext {}

